import { COUNTRIES, TIME_ZONES, FLAGS, asYouType, parsePhone, lengthProblem, exampleNumber, mainCountry } from "c/jformPhoneLib";

/**
 * Phone numbers with a country code, for the Phone field's country picker (c/jformPhoneInput).
 * Answers are stored in international format (+84912345678); the box shows the national format.
 * The rules cover the countries in c/jformPhoneLib, generated by scripts/phone/build.mjs; any
 * other country is "Other country", where the respondent types the full number with its code.
 * Field settings live in field.config: countryPicker, defaultCountry, detectCountry, strictNumber, mobileOnly.
 */

export { COUNTRIES, FLAGS };
export const OTHER = "OTHER";
const BY_ISO = new Map(COUNTRIES.map((c) => [c.iso, c]));
const FALLBACK_COUNTRY = "US";
/** Languages that point to one offered country even without a region subtag ("vi" is Vietnam). */
const LANGUAGE_COUNTRY = {
  vi: "VN", ja: "JP", ko: "KR", th: "TH", id: "ID", ms: "MY", km: "KH", si: "LK", bn: "BD", ur: "PK", he: "IL", iw: "IL",
  uk: "UA", pl: "PL", fi: "FI", sv: "SE", nb: "NO", nn: "NO", no: "NO", da: "DK", nl: "NL", it: "IT", tr: "TR", fil: "PH", tl: "PH"
};
/** Shortest and longest full numbers (country code included) accepted for "Other country". */
const OTHER_MIN_DIGITS = 7;
const OTHER_MAX_DIGITS = 15;

export function countryOf(iso) {
  return BY_ISO.get(iso) || null;
}
export function isOffered(iso) {
  return BY_ISO.has(iso);
}

// ------------------------------------------------------------ which country to start with

function browserEnv() {
  try {
    const languages = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language];
    return { timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone, languages };
  } catch (e) {
    return {};
  }
}
function regionOf(tag) {
  const m = /^[a-z]{2,3}(?:[-_][a-z]{4})?[-_]([a-z]{2})(?:$|[-_])/i.exec(String(tag || ""));
  return m ? m[1].toUpperCase() : null;
}

/**
 * The visitor's country among the offered ones, from the device's time zone, then the browser's
 * languages; null when neither says. Runs in the browser only: nothing is sent anywhere.
 */
export function detectCountry(env = browserEnv()) {
  const fromZone = env.timeZone && TIME_ZONES[env.timeZone];
  if (fromZone) return fromZone;
  const languages = (env.languages || []).filter(Boolean);
  for (const tag of languages) {
    const region = regionOf(tag);
    if (region && BY_ISO.has(region)) return region;
  }
  for (const tag of languages) {
    const country = LANGUAGE_COUNTRY[String(tag).toLowerCase().split(/[-_]/)[0]];
    if (country) return country;
  }
  return null;
}

/** The country an empty answer starts with: the visitor's when detection is on and finds one, else the field's default. */
export function startCountry(config, detect, env) {
  const c = config || {};
  if (detect && c.detectCountry) {
    const found = detectCountry(env);
    if (found) return found;
  }
  return BY_ISO.has(c.defaultCountry) ? c.defaultCountry : FALLBACK_COUNTRY;
}

/** The offered country of a locale such as "en-AU", else the fallback; new Phone fields default to the builder's. */
export function localeCountry(locale) {
  const region = regionOf(locale);
  return region && BY_ISO.has(region) ? region : FALLBACK_COUNTRY;
}

// ------------------------------------------------------------ reading and writing numbers

/** Digits only, keeping a leading +. */
export function cleanNumber(text) {
  const s = String(text ?? "").trim();
  const digits = s.replace(/\D/g, "");
  return s.startsWith("+") ? `+${digits}` : digits;
}

/** The number box text while typing: national format for an offered country, as typed for "Other country". */
export function formatTyping(text, iso) {
  const clean = cleanNumber(text);
  if (!clean || iso === OTHER || !BY_ISO.has(iso) || clean.startsWith("+")) return String(text ?? "");
  return asYouType(iso).input(clean);
}

/**
 * The answer to store for what is in the box: international format (+ and digits) when there is a number,
 * "" when there is none. A number typed with + keeps its own code; "Other country" always gets one.
 */
export function toAnswer(text, iso) {
  const clean = cleanNumber(text);
  if (!clean || clean === "+") return "";
  if (clean.startsWith("+")) return clean;
  if (iso === OTHER || !BY_ISO.has(iso)) return `+${clean}`;
  const typed = asYouType(iso);
  typed.input(clean);
  return typed.getNumberValue() || `+${BY_ISO.get(iso).dial}${clean}`;
}

/**
 * The country and box text for a stored answer. An international answer picks its own country; a
 * number without + (a prefilled value) is read in the fallback country.
 */
export function readAnswer(answer, fallbackIso) {
  const value = cleanNumber(answer);
  if (!value || value === "+") return { iso: fallbackIso, text: "" };
  if (!value.startsWith("+")) return { iso: fallbackIso, text: formatTyping(value, fallbackIso) };
  const parsed = parsePhone(value);
  if (parsed && BY_ISO.has(parsed.country)) return { iso: parsed.country, text: parsed.formatNational() };
  const main = parsed && mainCountry(parsed.countryCallingCode);
  if (main && BY_ISO.has(main)) return { iso: main, text: formatTyping(parsed.nationalNumber, main) };
  return { iso: OTHER, text: value };
}

/** A sample number for the country in national format, for the placeholder. */
export function examplePlaceholder(iso) {
  if (iso === OTHER) return "+1 234 567 8900";
  try {
    const sample = BY_ISO.has(iso) ? exampleNumber(iso) : undefined;
    return sample ? sample.formatNational() : "";
  } catch (e) {
    return "";
  }
}

// ------------------------------------------------------------ checking a number

function countryForAnswer(value) {
  const parsed = parsePhone(value);
  if (parsed && BY_ISO.has(parsed.country)) return { parsed, country: BY_ISO.get(parsed.country) };
  const code = /^\+(\d{1,3})/.exec(value);
  for (let n = 1; code && n <= code[1].length; n++) {
    const main = mainCountry(code[1].slice(0, n));
    if (main && BY_ISO.has(main)) return { parsed, country: BY_ISO.get(main) };
  }
  return { parsed, country: null };
}

/**
 * Why an answer is not an acceptable number, or null. Always checks the length for the country;
 * strictNumber also checks the number ranges the country uses; mobileOnly accepts mobile numbers
 * only (in the US and Canada, where the two cannot be told apart, any valid number).
 */
export function phoneProblem(answer, config) {
  const c = config || {};
  const value = cleanNumber(answer);
  if (!value || value === "+") return null;
  if (!value.startsWith("+")) return "Enter the number with its country code.";
  const { parsed, country } = countryForAnswer(value);
  if (!country) {
    const digits = value.length - 1;
    return digits >= OTHER_MIN_DIGITS && digits <= OTHER_MAX_DIGITS ? null : "Enter the full number, starting with + and the country code.";
  }
  const length = lengthProblem(value);
  if (length === "TOO_SHORT") return `This number is too short for ${country.name}.`;
  if (length === "TOO_LONG") return `This number is too long for ${country.name}.`;
  if (length) return `Enter a valid phone number for ${country.name}.`;
  if ((c.strictNumber || c.mobileOnly) && !(parsed && parsed.isValid())) return `Enter a valid phone number for ${country.name}.`;
  if (c.mobileOnly && !["MOBILE", "FIXED_LINE_OR_MOBILE"].includes(parsed.getType())) return "Enter a mobile number.";
  return null;
}
